function avatarImage(avatar){const palette=['#f7c9d7','#cdbdff','#bdebd8','#ffd5a4','#bde2ff','#ffd2bd','#d5efb5','#ffc3e1','#c9d1ff','#ffe39f','#d9c4ab','#b5e5de'];const i=Math.max(0,profileAvatarOptions.indexOf(avatar));const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 320"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${palette[i]}"/><stop offset="1" stop-color="#ffffff"/></linearGradient></defs><rect width="320" height="320" rx="160" fill="url(#g)"/><circle cx="160" cy="160" r="132" fill="#ffffff55"/><text x="160" y="205" text-anchor="middle" font-size="158" font-family="system-ui, sans-serif">${avatar}</text></svg>`;return `data:image/svg+xml,${encodeURIComponent(svg)}`}
function addProfileEmojiBadges(){app.querySelectorAll('.person-card > img,.person-tile > img').forEach(img=>{const card=img.parentElement;if(!card||card.querySelector(':scope > .profile-emoji'))return;const key=img.alt||img.src||'kindred';let hash=0;for(const char of key)hash=(hash*31+char.codePointAt(0))>>>0;const badge=document.createElement('span');badge.className='profile-emoji';badge.textContent=profileEmojis[hash%profileEmojis.length];badge.setAttribute('aria-label','Profile emoji');card.append(badge)})}
new MutationObserver(addProfileEmojiBadges).observe(app,{childList:true,subtree:true});
