async function apiRequest(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(apiToken())headers.Authorization=`Bearer ${apiToken()}`;const response=await fetch(`/api${path}`,{...options,headers,body:options.body===undefined?undefined:JSON.stringify(options.body)});const data=response.status===204?{}:await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Request failed (${response.status}).`);return data}
function fromApiProfile(p){if(!p)return null;return{id:p.id,name:p.displayName,age:p.age,birthDate:p.birthDate||'',gender:p.gender,looking:Array.isArray(p.interestedIn)?p.interestedIn[0]||'Everyone':p.looking||'Everyone',relation:p.relationshipGoal||p.relation,city:p.city||'',bio:p.bio||'',tags:p.interests||p.tags||[],img:p.photoUrl||p.img||'',avatar:p.avatar||'',interestedIn:p.interestedIn||[],chemistryAnswers:p.chemistryAnswers||{},personalityTwin:p.personalityTwin||''}}
function getAge(birthDate){if(!birthDate)return 0;const d=new Date(`${birthDate}T00:00:00Z`),now=new Date();let age=now.getUTCFullYear()-d.getUTCFullYear();if(now.getUTCMonth()<d.getUTCMonth()||(now.getUTCMonth()===d.getUTCMonth()&&now.getUTCDate()<d.getUTCDate()))age--;return Number.isFinite(age)?age:0}
function latestAdultBirthDate(){const d=new Date();d.setUTCFullYear(d.getUTCFullYear()-18);return d.toISOString().slice(0,10)}
let toastTimer;
function save(){const persisted={...state,profile:state.profile?{...state.profile}:undefined};delete persisted.phone;if(persisted.profile)delete persisted.profile.birthDate;localStorage.setItem('kindred-state',JSON.stringify(persisted))}
function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function brand(){return '<div class="brand"><span class="brand-mark">k</span>kindred</div>'}
function showLogin(){state.stage='login';save();render()}
function render(){if(state.stage==='login'||state.stage==='otp')renderLogin();else if(state.stage==='setup')renderSetup();else renderApp()}
function renderLogin(){app.innerHTML=`<div class="auth-shell"><section class="auth-panel">${brand()}<div class="auth-content"><div class="eyebrow">A little more intentional</div><h1>Good things<br>start with hello.</h1><p class="lead">Meet people who are looking for the same kind of connection you are.</p><label class="field-label" for="phone">Your phone number</label><div class="phone-row"><select aria-label="Country code"><option>🇺🇸 +1</option><option>🇮🇳 +91</option><option>🇬🇧 +44</option><option>🇨🇦 +1</option><option>🇦🇺 +61</option></select><input id="phone" type="tel" autocomplete="tel" placeholder="(555) 000-0000" maxlength="16"></div><label class="field-label" for="password" style="margin-top:16px">Password</label><input id="password" type="password" autocomplete="current-password" minlength="12" maxlength="128" placeholder="At least 12 characters"><p class="tiny-note">Sign in or create an account with your phone number and password. No SMS or Twilio account needed. Your number is not verified and stays private.</p><button id="sign-in" class="primary-btn full">Sign in</button><button id="register" class="secondary-btn full" style="margin-top:10px">Create account</button>${BACKEND_ENABLED?'':'<button class="text-btn" id="demo">Explore the demo instead →</button>'}</div><div class="auth-footer">By continuing, you agree to our Terms and Privacy Policy.</div></section><section class="auth-art"><div class="art-copy"><div class="art-tag">More than a first impression</div><h2>Here for what<br>could be.</h2><p>Meet with intention. Take your time. See where a good conversation goes.</p></div></section></div>`;
 const authenticate=async(mode)=>{const input=document.getElementById('phone'),digits=input.value.replace(/\D/g,''),dial=document.querySelector('.phone-row select').value.match(/\+\d+/)?.[0]||'+1',password=document.getElementById('password').value;if(digits.length<7){notify('Enter a valid phone number to continue.');return}if(password.length<12){notify('Use a password with at least 12 characters.');return}state.phone=`${dial}${digits}`;if(BACKEND_ENABLED){try{const result=await apiRequest('/auth/password',{method:'POST',body:{phone:state.phone,password,mode}});sessionStorage.setItem('kindred-token',result.token);state.profile=fromApiProfile(result.profile);state.stage=state.profile?'app':'setup'}catch(e){notify(e.message);return}}else state.stage=state.profile?'app':'setup';save();render()};
 document.getElementById('sign-in').onclick=()=>authenticate('login');document.getElementById('register').onclick=()=>authenticate('register');document.getElementById('password').onkeydown=e=>{if(e.key==='Enter')authenticate('login')};
 document.getElementById('demo')?.addEventListener('click',()=>{state.stage=state.profile?'app':'setup';save();render()})}
function renderSetup(){const p=state.profile||{};app.innerHTML=`<div class="setup-shell"><section class="setup-card"><div class="setup-top">${brand()}<div class="steps"><span class="active"></span><span class="active"></span></div></div><div class="eyebrow">Your profile, your pace</div><h1>Let’s make it you.</h1><p class="lead">A few details help us introduce you to people looking for the same kind of connection.</p><div class="form-grid"><div class="field"><label for="name">First name</label><input id="name" placeholder="What should we call you?" value="${escapeHtml(p.name||'')}"></div><div class="field"><label for="birth-date">Date of birth (18+)</label><input id="birth-date" type="date" max="${latestAdultBirthDate()}" value="${escapeHtml(p.birthDate||'')}"></div></div><div class="form-grid"><div class="field"><label for="gender">I identify as</label><select id="gender"><option value="">Choose your gender</option>${['Woman','Man','Non-binary','Self-describe','Prefer not to say'].map(x=>`<option ${p.gender===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="looking">I’d like to meet</label><select id="looking"><option value="">Choose who you’d like to meet</option>${['Women','Men','Everyone'].map(x=>`<option ${p.looking===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>What kind of relationship are you looking for?</label><div class="choice-grid">${[['A long-term relationship','Something lasting'],['A serious relationship','Ready to build'],['Life partner','My person'],['Something meaningful','Open to connection'],['Casual dating','See how it feels'],['Still figuring it out','Let it unfold']].map(([a,b])=>`<button class="choice ${p.relation===a?'selected':''}" data-relation="${a}">${a}<small>${b}</small></button>`).join('')}</div></div><div class="setup-actions"><button class="text-btn" id="setup-back">← Back</button><button class="primary-btn" id="finish">Find my people&nbsp; →</button></div><p class="tiny-note">Kindred is for adults 18+. Your gender and relationship preferences help personalize your recommendations.</p></section></div>`;
 document.querySelectorAll('[data-relation]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-relation]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.getElementById('setup-back').onclick=()=>{state.stage='login';save();render()};document.getElementById('finish').onclick=async()=>{const name=document.getElementById('name').value.trim(),birthDate=document.getElementById('birth-date').value,age=getAge(birthDate),gender=document.getElementById('gender').value,looking=document.getElementById('looking').value,relation=document.querySelector('[data-relation].selected')?.dataset.relation;if(!name||age<18||age>120||!gender||!looking||!relation){notify('Enter a valid birth date (18+) and complete each profile field.');return}let profile={name,age,birthDate,gender,looking,relation};if(BACKEND_ENABLED){try{const result=await apiRequest('/profile',{method:'PUT',body:{displayName:name,birthDate,gender,interestedIn:[looking],relationshipGoal:relation,city:'',bio:'',interests:[],photoUrl:''}});profile=fromApiProfile(result.profile)}catch(e){notify(e.message);return}}state.profile=profile;state.stage='app';save();render()}}
function buildLocalTwin(a){const pace={'slow-and-steady':'slow-and-steady','balanced':'balanced','spontaneous':'spontaneous'}[a.connectionPace]||'thoughtful';const communication={'thoughtful-texts':'thoughtful texter','voice-notes':'voice-note lover','face-to-face':'in-person communicator'}[a.communication]||'curious communicator';const energy={'cozy-and-quiet':'cozy at heart','a-little-of-both':'socially balanced','always-out':'always up for a plan'}[a.socialEnergy]||'open to connection';return `Your Personality Twin is ${pace}, a ${communication}, and ${energy}. You tend to feel most connected when people respect your pace and make room for honest, comfortable conversation.`}
async function renderChemistry(v){let answers=state.profile?.chemistryAnswers||state.chemistryAnswers||{},twin=state.profile?.personalityTwin||'';if(BACKEND_ENABLED){try{const result=await apiRequest('/chemistry');answers=result.answers||{};twin=result.personalityTwin||''}catch(e){notify(e.message)}}v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Get to know your connection style</div><h1>Digital Chemistry Test.</h1><p>Six quick picks help Kindred understand what comfortable connection means to you.</p></div></div><div class="chemistry-layout"><form class="chemistry-form" id="chemistry-form">${chemistryQuestions.map((q,i)=>`<fieldset class="chem-question"><legend><span>${String(i+1).padStart(2,'0')}</span>${q.title}</legend><div class="chem-options">${q.options.map(([value,label])=>`<label class="chem-option"><input type="radio" name="${q.key}" value="${value}" ${answers[q.key]===value?'checked':''} required><span>${label}</span></label>`).join('')}</div></fieldset>`).join('')}<button class="primary-btn full" type="submit">Save my chemistry</button><p class="tiny-note">Your answers are private. We use them to rank mutual comfort, not to decide who you should date.</p></form><aside class="personality-twin"><div class="twin-orbit">✧</div><div class="eyebrow">Your AI-inspired profile</div><h2>Personality Twin</h2><p id="twin-copy">${escapeHtml(twin||'Finish the test to reveal your connection style.')}</p><div class="twin-note">A reflection of your choices, not a diagnosis or a promise about compatibility.</div><button class="secondary-btn" id="chemistry-discover">See your matches</button></aside></div>`;document.getElementById('chemistry-form').onsubmit=async e=>{e.preventDefault();const formData=new FormData(e.currentTarget),next=Object.fromEntries(chemistryQuestions.map(q=>[q.key,formData.get(q.key)]));try{let result={answers:next,personalityTwin:buildLocalTwin(next)};if(BACKEND_ENABLED)result=await apiRequest('/chemistry',{method:'PUT',body:{answers:next}});state.chemistryAnswers=result.answers;state.profile={...(state.profile||{}),chemistryAnswers:result.answers,personalityTwin:result.personalityTwin};save();document.getElementById('twin-copy').textContent=result.personalityTwin;notify('Your Personality Twin is ready. Mutual comfort scores are updated.')}catch(error){notify(error.message)}};document.getElementById('chemistry-discover').onclick=()=>{state.tab='discover';save();renderApp()}}
function currentPerson(){return people.find(p=>!state.passed.includes(p.id)&&!state.liked.includes(p.id))}
function renderApp(){initializeKindredCallPresence();const nav=[['discover','⌕','Discover',''],['likes','♡',BACKEND_ENABLED?'Matches':'Likes',BACKEND_ENABLED?'':state.liked.length||''],['messages','▤','Messages',BACKEND_ENABLED?'':Object.keys(state.chats).length||''],['profile','◉','My profile',''],['chemistry','✧','Chemistry','']];app.innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<div class="nav-label">Your space</div>${nav.map(([id,ico,label,count])=>`<button class="nav-btn ${state.tab===id?'active':''}" data-tab="${id}"><span class="nav-ico">${ico}</span><span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><div class="nav-label">A little reminder</div><div class="surface-card" style="padding:13px;margin:0 3px 15px"><p style="font-size:11px">Good connections take time. Be kind, be curious, be yourself.</p></div><div class="profile-mini"><img class="avatar" src="${remoteImage(state.profile||{img:'photo-1534528741775-53994a69daeb'},100)}"><div>${escapeHtml(state.profile?.name||'Your profile')}<small>${escapeHtml(state.profile?.relation||'Looking for connection')}</small></div></div></div></aside><section class="main-area"><div class="topbar"><div class="topbar-note">${greeting()}, ${escapeHtml(state.profile?.name||'friend')} <span>✳</span></div><div class="topbar-actions"><button class="icon-btn" id="notif" aria-label="Enable notifications" title="Enable browser notifications">♧<i class="online-dot"></i></button><button class="icon-btn" id="profile-shortcut" aria-label="Profile">☺</button></div></div><div id="view"></div></section><nav class="mobile-nav">${nav.map(([id,ico,label])=>`<button class="${state.tab===id?'active':''}" data-tab="${id}"><b>${ico}</b>${label}</button>`).join('')}</nav></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;save();renderApp()});document.getElementById('notif').onclick=()=>requestKindredNotifications();document.getElementById('profile-shortcut').onclick=()=>{state.tab='profile';renderApp()};const v=document.getElementById('view');if(state.tab==='discover')renderDiscover(v);if(state.tab==='likes')renderLikes(v);if(state.tab==='messages')renderMessages(v);if(state.tab==='profile')renderProfile(v);if(state.tab==='chemistry')renderChemistry(v)}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'}
function remoteImage(p,w=700){return p?.avatar?avatarImage(p.avatar):image(p?.photoUrl||p?.img||'photo-1524504388940-b1c1722653e1',w)}
async function renderApiDiscover(v){const query=state.query||'';v.innerHTML=`<div class="discover-head"><div><div class="eyebrow">A good place to begin</div><h1>People worth meeting.</h1><p>People ranked by shared chemistry and mutual comfort.</p></div><button class="filter-btn" id="edit-profile">Edit profile</button></div><form class="discover-search" id="api-search"><label for="profile-search">Find your kind of person</label><div class="search-control"><span aria-hidden="true">⌕</span><input id="profile-search" type="search" placeholder="Search names, places, interests…" value="${escapeHtml(query)}"><button type="submit">Search</button></div></form><div id="api-discover-results"><div class="empty-state"><p>Finding your people…</p></div></div>`;document.getElementById('edit-profile').onclick=()=>{state.stage='setup';render()};document.getElementById('api-search').onsubmit=e=>{e.preventDefault();state.query=document.getElementById('profile-search').value.trim();save();renderApiDiscover(v)};try{const result=await apiRequest(`/profiles?search=${encodeURIComponent(query)}`);if(!v.isConnected)return;const profiles=result.profiles||[],container=document.getElementById('api-discover-results');if(query){container.innerHTML=`<section class="search-results"><div class="search-result-head"><div><div class="eyebrow">Your search</div><h2>${profiles.length?`${profiles.length} ${profiles.length===1?'person':'people'} to explore`:'No matches just yet'}</h2></div><button class="text-btn" id="clear-api-search">Clear search</button></div>${profiles.length?`<div class="people-grid">${profiles.map(remoteTile).join('')}</div>`:`<div class="empty-state"><div class="emoji">⌕</div><p>Try another name, neighborhood, or interest.</p></div>`}</section>`;document.getElementById('clear-api-search').onclick=()=>{state.query='';save();renderApiDiscover(v)};container.querySelectorAll('[data-api-match]').forEach(b=>b.onclick=()=>{const p=profiles.find(x=>x.id===b.dataset.apiMatch);if(p)sendApiLike(p,v)});return}const p=profiles[0];if(!p){container.innerHTML=`<div class="empty-state"><div class="emoji">✿</div><h2>No new profiles right now.</h2><p>Try search again later as more people join.</p></div>`;return}container.innerHTML=`<div class="discover-layout"><article class="person-card"><img src="${remoteImage(p,900)}" alt="${escapeHtml(p.displayName)}'s profile"><div class="card-top"><span class="pill">✧ &nbsp; ${p.compatibilityScore===null?'Take Chemistry Test':`${p.compatibilityScore}% mutual comfort`}</span></div><div class="card-copy"><h2>${escapeHtml(p.displayName)}, ${p.age}</h2><p>⌖ &nbsp;${escapeHtml(p.city||'Location not added')} &nbsp; · &nbsp; ${escapeHtml(p.relationshipGoal)}</p><div class="bio">${escapeHtml(p.bio||'Let’s start with a good conversation.')}</div><div class="interest-row">${(p.interests||[]).map(x=>`<span class="interest">${escapeHtml(x)}</span>`).join('')}</div></div><div class="card-actions"><button class="round-action" id="api-pass" aria-label="Pass">×</button><button class="round-action like" id="api-like" aria-label="Match">♡</button><button class="round-action" id="api-wave" aria-label="Send a wave">✧</button></div></article><div class="side-stack"><article class="surface-card intent-box"><h3>Your intention</h3><p>Profiles are filtered to your preferences.</p><span class="intent-chip">${escapeHtml(state.profile?.relation||'')}</span></article><article class="surface-card"><h3>Conversation starter</h3><p>Try asking about one of their interests. Curiosity makes a lovely first hello.</p></article></div></div>`;document.getElementById('api-pass').onclick=async()=>{try{await apiRequest(`/profiles/${p.id}/pass`,{method:'POST'});renderApiDiscover(v)}catch(e){notify(e.message)}};document.getElementById('api-like').onclick=()=>sendApiLike(p,v);document.getElementById('api-wave').onclick=()=>sendApiLike(p,v)}catch(e){if(v.isConnected)document.getElementById('api-discover-results').innerHTML=`<div class="empty-state"><h2>Couldn’t load profiles.</h2><p>${escapeHtml(e.message)}</p></div>`}}
function remoteTile(p){return `<article class="person-tile"><img src="${remoteImage(p,500)}" alt="${escapeHtml(p.displayName)}'s profile"><div class="tile-copy"><strong>${escapeHtml(p.displayName)}, ${p.age}</strong><span class="compatibility-badge">${p.compatibilityScore===null?'Take the Chemistry Test':`✧ ${p.compatibilityScore}% mutual comfort`}</span><p>${escapeHtml(p.city||'Location not added')} · ${escapeHtml(p.relationshipGoal)}</p><p class="search-tags">${(p.interests||[]).slice(0,3).map(escapeHtml).join(' · ')}</p><div class="tile-actions"><button class="tile-like" data-api-match="${p.id}">♡ Match</button></div></div></article>`}
