function match(person,v,wave=false){if(!state.liked.includes(person.id))state.liked.push(person.id);state.index++;save();if(!state.chats[person.id])state.chats[person.id]=[{text:wave?'A wave from you 👋':'You liked each other — say hello!',mine:true,time:'Now'}];renderApp();const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML=`<div class="modal"><div class="match-heart">♡</div><div class="eyebrow">A lovely beginning</div><h2>You and ${person.name} are a match.</h2><p>You’re both looking for a similar kind of connection. A thoughtful hello can make someone’s day.</p><img src="${image(person.img,200)}" class="avatar" style="width:62px;height:62px" alt="${person.name}"><div class="modal-actions"><button class="secondary-btn" data-close>Keep exploring</button><button class="primary-btn" data-message>Say hello</button></div></div>`;document.body.append(overlay);overlay.querySelector('[data-close]').onclick=()=>overlay.remove();overlay.querySelector('[data-message]').onclick=()=>{overlay.remove();state.tab='messages';state.selectedChat=person.id;renderApp()}}
async function renderApiMatches(v){v.innerHTML=`<div class="section-title"><div><div class="eyebrow">A little mutual interest</div><h1>Your matches.</h1><p>Say hello and see where it goes.</p></div></div><div class="empty-state"><p>Loading matches…</p></div>`;try{const {matches=[]}=await apiRequest('/matches');if(!v.isConnected)return;v.innerHTML=`<div class="section-title"><div><div class="eyebrow">A little mutual interest</div><h1>Your matches.</h1><p>Say hello and see where it goes.</p></div></div>${matches.length?`<div class="people-grid">${matches.map(m=>`<article class="person-tile"><img src="${remoteImage(m,500)}" alt="${escapeHtml(m.displayName)}'s profile"><div class="tile-copy"><strong>${escapeHtml(m.displayName)}, ${m.age}</strong><p>${escapeHtml(m.city||'Location not added')} · ${escapeHtml(m.relationshipGoal)}</p><div class="tile-actions"><button class="tile-like" data-open-match="${m.id}">Message</button><button data-voice-match="${m.id}">☎</button></div></div></article>`).join('')}</div>`:`<div class="empty-state"><div class="emoji">♡</div><h2>Your next connection starts here.</h2><p>Like a profile; when they like you back, you’ll match.</p><button class="primary-btn" id="go-discover">Meet people</button></div>`}`;document.getElementById('go-discover')?.addEventListener('click',()=>{state.tab='discover';renderApp()});v.querySelectorAll('[data-open-match]').forEach(b=>b.onclick=()=>{state.selectedChat=b.dataset.openMatch;state.tab='messages';renderApp()});v.querySelectorAll('[data-voice-match]').forEach(b=>b.onclick=()=>{const m=matches.find(x=>x.id===b.dataset.voiceMatch);openCall(m,'voice')})}catch(e){if(v.isConnected)v.innerHTML=`<div class="empty-state"><h2>Couldn’t load matches.</h2><p>${escapeHtml(e.message)}</p></div>`}}
