function apiSocket(){if(!window.io)return null;if(!realtimeSocket){realtimeSocket=window.io({autoConnect:false,auth:{token:apiToken()}});realtimeSocket.connect()}return realtimeSocket}
async function renderApiMessagesLegacy(v){v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Good conversations happen here</div><h1>Messages.</h1><p>Loading conversations…</p></div></div>`;try{const {matches=[]}=await apiRequest('/matches');if(!v.isConnected)return;const selected=matches.find(m=>m.id===state.selectedChat)||matches[0];if(!selected){v.innerHTML=`<div class="section-title"><div><div class="eyebrow">It starts with hello</div><h1>Messages.</h1><p>Your conversations will live here.</p></div></div><div class="empty-state"><div class="emoji">✉</div><h2>No matches yet.</h2><p>When someone likes you back, your conversation will show up here.</p><button class="primary-btn" id="go-discover">Meet people</button></div>`;document.getElementById('go-discover').onclick=()=>{state.tab='discover';renderApp()};return}state.selectedChat=selected.id;const {messages=[]}=await apiRequest(`/matches/${selected.id}/messages`);if(!v.isConnected)return;v.innerHTML=`<div class="section-title"><div><div class="eyebrow">Good conversations happen here</div><h1>Messages.</h1><p>Say something kind. See where it goes.</p></div></div><div class="chat-layout"><aside class="chat-list"><h3>Matches</h3>${matches.map(m=>`<button class="chat-person ${m.id===selected.id?'active':''}" data-chat-id="${m.id}"><img src="${remoteImage(m,120)}" alt=""><div><strong>${escapeHtml(m.displayName)}</strong><small>${escapeHtml(m.lastMessage?.body||'Start a conversation')}</small></div></button>`).join('')}</aside><section class="chat-window"><header class="chat-head"><div class="chat-head-person"><img src="${remoteImage(selected,120)}" alt=""><div><strong>${escapeHtml(selected.displayName)}</strong><small>● &nbsp;Matched on Kindred</small></div></div><div class="call-actions"><button class="icon-btn" id="voice-call" title="Start a voice call">☎</button><button class="icon-btn" id="video-call" title="Start a video call">▣</button></div></header><div class="messages" id="messages">${messages.map(m=>`<div class="message ${m.senderId===state.profile?.id?'mine':''}">${escapeHtml(m.body)}<time>${new Date(m.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')}</div><form class="chat-compose" id="compose"><input id="message-input" placeholder="Write a kind hello…" autocomplete="off" aria-label="Message"><button>Send</button></form></section></div>`;const socket=apiSocket();if(socket){socket.emit('match:join',selected.id);socket.off('message:new');socket.on('message:new',()=>{if(state.tab==='messages'&&state.selectedChat===selected.id)renderApiMessages(v)})}v.querySelectorAll('[data-chat-id]').forEach(b=>b.onclick=()=>{state.selectedChat=b.dataset.chatId;renderApiMessages(v)});document.getElementById('compose').onsubmit=async e=>{e.preventDefault();const input=document.getElementById('message-input'),body=input.value.trim();if(!body)return;try{await apiRequest(`/matches/${selected.id}/messages`,{method:'POST',body:{body}});renderApiMessages(v)}catch(err){notify(err.message)}};document.getElementById('voice-call').onclick=()=>openCall({name:selected.displayName},'voice');document.getElementById('video-call').onclick=()=>openCall({name:selected.displayName},'video')}catch(e){if(v.isConnected)v.innerHTML=`<div class="empty-state"><h2>Couldn’t load messages.</h2><p>${escapeHtml(e.message)}</p></div>`}}
