async function boot(){if(BACKEND_ENABLED){if(!apiToken()){state.stage='login'}else{try{const {profile}=await apiRequest('/me');state.profile=fromApiProfile(profile);state.stage=state.profile?'app':'setup'}catch{sessionStorage.removeItem('kindred-token');state.stage='login'}}}render()}
boot();

