function openTruthDareGame(matchName,onSend){
 const modal=document.createElement('div');modal.className='modal-backdrop truth-dare-backdrop';
 modal.innerHTML=`<section class="truth-dare-modal" role="dialog" aria-modal="true" aria-labelledby="truth-dare-title"><button class="selfie-close" data-game-close aria-label="Close">×</button><div class="game-sparkle">🎲</div><div class="eyebrow">A little chat side quest</div><h2 id="truth-dare-title">Truth or Dare</h2><p class="game-intro">Pick a prompt for ${escapeHtml(matchName)}. Keep it kind and pass whenever you want.</p><div class="game-kind-picker"><button type="button" data-kind="Truth" class="selected">✨ Truth</button><button type="button" data-kind="Dare">🎯 Dare</button></div><article class="game-prompt-card"><span id="game-prompt-kind">YOUR TRUTH</span><p id="game-prompt-text"></p></article><button class="game-refresh" type="button" data-game-refresh>↻ Another prompt</button><div class="game-actions"><button class="secondary-btn" type="button" data-game-close>Maybe later</button><button class="primary-btn" type="button" data-game-send>Send to chat&nbsp; ↗</button></div><small class="game-safety">Keep personal details private. No pressure, just good vibes.</small></section></div>`;
 document.body.append(modal);
 let kind='Truth',prompt='';
 const draw=()=>{const choices=truthDarePrompts[kind];prompt=choices[Math.floor(Math.random()*choices.length)];modal.querySelector('#game-prompt-kind').textContent=`YOUR ${kind.toUpperCase()}`;modal.querySelector('#game-prompt-text').textContent=prompt};
 const close=()=>modal.remove();modal.querySelectorAll('[data-game-close]').forEach(button=>button.onclick=close);
 modal.querySelectorAll('[data-kind]').forEach(button=>button.onclick=()=>{kind=button.dataset.kind;modal.querySelectorAll('[data-kind]').forEach(option=>option.classList.toggle('selected',option===button));draw()});
 modal.querySelector('[data-game-refresh]').onclick=draw;
 modal.querySelector('[data-game-send]').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{await onSend(`🎲 Truth or Dare · ${kind}: ${prompt}\n(You can always pass!)`);close();notify('Your prompt is on its way!')}catch(error){button.disabled=false;notify(error.message||'Could not send that prompt.')}};
 draw();
}

